  // boxes for the crop: page coordinates, x as on the screen
  const box = (r) => ({ left: Math.round(r.l - SX), top: Math.round(r.t), width: Math.max(2, Math.round(r.r - r.l)), height: Math.max(2, Math.round(r.b - r.t)) });
