    if (docWidth > vw + 1) F.push({ check: 'off-viewport', sev: 'FAIL', id: 0, sel: '(the page)', text: '', stop: null, rects: [], msg: `the page is ${docWidth}px wide on a ${vw}px screen and scrolls sideways` });
